    's.translate.1': 'أترجمه بهاتفي.',
    's.translate.2': 'هل يمكنني أن أترجم هذا بسرعة؟',
    's.translate.3': 'لو سمحت، هل يمكنك التحدث إلى هاتفي قليلاً؟',
    'c.translate.q': 'ماذا مكتوب في هذه الورقة؟',
    'c.translate.a': 'لحظة، سأترجمها.',
    'l.understood': { m: 'أن تفهم وأن يفهمك الآخرون', f: 'أن تفهمي وأن يفهمك الآخرون' },
