    'c.aihelp.o1': { m: 'اطلب من HR أو Juridisch Loket أن يتحقّقوا منه.', f: 'اطلبي من HR أو Juridisch Loket أن يتحقّقوا منه.' }, // nagelezen (2e lezing)
