    'w.plukkar': "عربة القطف", // nagelezen (2e lezing)
    'w.bukken': "ينحني", // nagelezen (2e lezing)
    'w.drinken': "يشرب", // nagelezen (2e lezing)
    'w.hitte': "الحرّ (عندما يكون الجو حاراً جداً)", // nagelezen (2e lezing)
    's.greensafe.1': "هل رُشّت هذه الدفيئة؟", // nagelezen (2e lezing)
    's.greensafe.2': "سأذهب لأشرب قليلاً من الماء.", // nagelezen (2e lezing)
    's.greensafe.3': "أين عربة القطف؟", // nagelezen (2e lezing)
    'c.greensafe.q': "هل يمكنني أن أعمل في الدفيئة رقم ثلاثة؟", // nagelezen (2e lezing)
    'c.greensafe.a': "لا، ليس بعد. رُشّت للتو.", // nagelezen (2e lezing)
    'c.harvest': "سرعة العمل والأجر بالقطعة", // nagelezen (2e lezing)
    'c.harvest.b': { m: "في الدفيئة تعمل غالباً بسرعة ثابتة (tempo). بعض أصحاب العمل يدفعون حسب الصندوق أو الصف أو الكيلو: هذا هو الأجر بالقطعة (stukloon). حتى مع الأجر بالقطعة يجب أن تكسب على الأقل الحد الأدنى للأجور عن كل ساعة تعملها. تحقّق من المبلغ على rijksoverheid.nl. اكتب كل يوم ساعاتك وصناديقك، وقارنها بقسيمة راتبك. العمل بسرعة جيد، لكن العمل بأمان يأتي أولاً. معلومات عامة. لوضعك أنت: اسأل النقابة أو Juridisch Loket أو FairWork.", f: "في الدفيئة تعملين غالباً بسرعة ثابتة (tempo). بعض أصحاب العمل يدفعون حسب الصندوق أو الصف أو الكيلو: هذا هو الأجر بالقطعة (stukloon). حتى مع الأجر بالقطعة يجب أن تكسبي على الأقل الحد الأدنى للأجور عن كل ساعة تعملينها. تحقّقي من المبلغ على rijksoverheid.nl. اكتبي كل يوم ساعاتكِ وصناديقكِ، وقارنيها بقسيمة راتبكِ. العمل بسرعة جيد، لكن العمل بأمان يأتي أولاً. معلومات عامة. لوضعكِ أنتِ: اسألي النقابة أو Juridisch Loket أو FairWork." }, // nagelezen (2e lezing)
    'c.harvest.p': "كم صندوقاً أنهيت اليوم؟", // nagelezen (2e lezing)
    'c.harvest.s': { m: "يدفعون لك حسب الصندوق. في آخر الأسبوع، أجرك أقل بكثير من الحد الأدنى للأجور عن الساعات التي عملتها. ماذا تفعل؟", f: "يدفعون لكِ حسب الصندوق. في آخر الأسبوع، أجركِ أقل بكثير من الحد الأدنى للأجور عن الساعات التي عملتِها. ماذا تفعلين؟" }, // nagelezen (2e lezing)
    'c.harvest.o1': { m: "أرِ صاحب العمل قائمتك الخاصة بالساعات والصناديق.", f: "أري صاحب العمل قائمتكِ الخاصة بالساعات والصناديق." }, // nagelezen (2e lezing)
    'c.harvest.o2': { m: "لا تقل شيئاً واعمل أسرع في الأسبوع القادم، حتى تكسب أكثر.", f: "لا تقولي شيئاً واعملي أسرع في الأسبوع القادم، حتى تكسبي أكثر." }, // nagelezen (2e lezing)
    'c.harvest.o3': { m: "اقبل ذلك: مع الأجر بالقطعة، الأجر المنخفض أمر عادي.", f: "اقبلي ذلك: مع الأجر بالقطعة، الأجر المنخفض أمر عادي." }, // nagelezen (2e lezing)
    'c.harvest.w': { m: "مع الأجر بالقطعة يجب أن تحصل رغم ذلك على الحد الأدنى للأجور على الأقل عن كل ساعة عملتها. قائمتك الخاصة بالساعات والصناديق تساعدك أن تُظهر ما فعلته. إذا لم يُصحَّح الأمر، اطلب المساعدة.", f: "مع الأجر بالقطعة يجب أن تحصلي رغم ذلك على الحد الأدنى للأجور على الأقل عن كل ساعة عملتِها. قائمتكِ الخاصة بالساعات والصناديق تساعدكِ أن تُظهري ما فعلتِه. إذا لم يُصحَّح الأمر، اطلبي المساعدة." }, // nagelezen (2e lezing)
    'c.greensafe': "الحرّ والمبيدات", // nagelezen (2e lezing)
    'c.greensafe.b': { m: "في الدفيئة قد يصبح الجو حاراً جداً، حتى في الربيع. اشرب الماء كثيراً، حتى قبل أن تشعر بالعطش، وخذ استراحاتك في مكان بارد. تشعر بدوخة أو غثيان، أو عندك صداع؟ توقّف وأخبر أحداً. أحياناً تُرشّ النباتات بمواد كيميائية (spuitmiddelen). الدفيئة التي رُشّت للتو يكون على بابها غالباً لافتة. لا تدخل حتى يقول مشرفك إن المكان أصبح آمناً من جديد. معلومات عامة. لوضعك أنت: اسأل صاحب العمل أو النقابة أو Juridisch Loket.", f: "في الدفيئة قد يصبح الجو حاراً جداً، حتى في الربيع. اشربي الماء كثيراً، حتى قبل أن تشعري بالعطش، وخذي استراحاتكِ في مكان بارد. تشعرين بدوخة أو غثيان، أو عندكِ صداع؟ توقّفي وأخبري أحداً. أحياناً تُرشّ النباتات بمواد كيميائية (spuitmiddelen). الدفيئة التي رُشّت للتو يكون على بابها غالباً لافتة. لا تدخلي حتى يقول مشرفكِ إن المكان أصبح آمناً من جديد. معلومات عامة. لوضعكِ أنتِ: اسألي صاحب العمل أو النقابة أو Juridisch Loket." }, // nagelezen (2e lezing)
    'c.greensafe.p': "هل يمكنني أن أعمل في هذه الدفيئة الآن؟", // nagelezen (2e lezing)
    'c.greensafe.s': { m: "رُشّت دفيئة هذا الصباح. على الباب لافتة. زميل يقول: «هيا، إنها لحظة فقط.» ماذا تفعل؟", f: "رُشّت دفيئة هذا الصباح. على الباب لافتة. زميل يقول: «هيا، إنها لحظة فقط.» ماذا تفعلين؟" }, // nagelezen (2e lezing)
    'c.greensafe.o1': { m: "ابقَ خارجاً، واسأل متى يصبح آمناً.", f: "ابقي خارجاً، واسألي متى يصبح آمناً." }, // nagelezen (2e lezing)
    'c.greensafe.o2': { m: "ادخل بسرعة واحبس أنفاسك.", f: "ادخلي بسرعة واحبسي أنفاسكِ." }, // nagelezen (2e lezing)
    'c.greensafe.o3': { m: "ادخل، واغسل يديك جيداً بعد ذلك.", f: "ادخلي، واغسلي يديكِ جيداً بعد ذلك." }, // nagelezen (2e lezing)
    'c.greensafe.w': { m: "المبيدات قد تؤذي جلدك وعينيك ورئتيك، حتى عندما لا تشم أي رائحة. بعد الرش هناك وقت انتظار قبل أن يُسمح بالدخول من جديد. مشرفك يعرف متى ينتهي.", f: "المبيدات قد تؤذي جلدكِ وعينيكِ ورئتيكِ، حتى عندما لا تشمّين أي رائحة. بعد الرش هناك وقت انتظار قبل أن يُسمح بالدخول من جديد. مشرفكِ يعرف متى ينتهي." }, // nagelezen (2e lezing)
